import sys
from collections import deque

input = sys.stdin.read
data = input().split()

n = int(data[0])
arr = list(map(int, data[1:]))

queue = deque()
for i in range(n):
    if arr[i] == 0:
        queue.append(i)

result = []
for i in range(n):
    if arr[i] == 0:
        result.append(0)
    else:
        result.append(min([abs(i - j) for j in queue]))

for res in result:
    print(res)

